"""Tests for gap_audit.py."""

from gap_audit import audit

# Inline sample: 12 lines covering a gap, a duplicate, a malformed line,
# and two different years (unsorted on purpose).
SAMPLE_LINES = [
    "INV-2026-0001",
    "INV-2026-0003",   # gap: 2026-0002 missing after this pair
    "INV-2026-0005",
    "INV-2026-0005",   # duplicate
    "INV-2026-0008",
    "INV-2027-0002",
    "INV-2027-0004",
    "INV-2027-0004",   # duplicate
    "INV-2027-0006",
    "not-an-invoice",  # malformed
    "INV-2027-0009",
    "INV-2026-0002",
]


def test_audit_report():
    assert audit(SAMPLE_LINES) == {
        "2026": {
            # present: 1, 2, 3, 5, 8 -> gaps inside [1, 8]
            "missing": [4, 6, 7],
            "duplicates": [5],
        },
        "2027": {
            # present: 2, 4, 6, 9 -> gaps inside [2, 9]
            "missing": [3, 5, 7, 8],
            "duplicates": [4],
        },
        "rejected": [
            {"line": 10, "text": "not-an-invoice"},
        ],
    }


def test_empty_input():
    assert audit([]) == {}


def test_rejected_includes_line_numbers():
    report = audit(["garbage one", "INV-2030-0042", "", "INV-20-0042"])
    assert report["rejected"] == [
        {"line": 1, "text": "garbage one"},
        {"line": 3, "text": ""},
        {"line": 4, "text": "INV-20-0042"},
    ]
    assert report["2030"] == {"missing": [], "duplicates": []}

